import {folds,fields,delta,days} from './calculations.js';
import {foldTransition,fatMassChange,comparisonReady,markerRadius} from './progress-model.js';
const $=s=>document.querySelector(s),f=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),sign=n=>(n>0?'+':'')+f(n),d=s=>s.split('-').reverse().join('/');
const locations={sfChest:[103,125,'front'],sfAxillary:[85,151,'front'],sfTriceps:[438,150,'back'],sfSubscapular:[399,132,'back'],sfAbdomen:[114,184,'front'],sfSuprailiac:[91,214,'front'],sfThigh:[104,275,'front']};
let first,last,selected='sfAbdomen',frame=0,position=0;
const outline='<circle cx="125" cy="45" r="23"/><path d="M111 69 L139 69 L144 84 C162 85 177 92 182 108 L204 186 Q208 199 198 203 Q188 207 183 194 L161 139 L157 193 Q173 222 163 259 L151 349 Q150 361 162 371 Q166 379 151 380 L131 380 L126 271 L119 271 L114 380 L93 380 Q80 379 85 371 Q98 361 97 349 L86 259 Q76 222 92 193 L88 139 L66 194 Q61 207 51 203 Q41 199 46 186 L68 108 Q73 91 106 84 Z"/>';
function person(offset,back){return `<g transform="translate(${offset} 0)" class="body-outline">${outline}<path class="body-line" d="${back?'M125 95 L125 204 M102 119 Q125 139 148 119':'M100 112 Q112 119 124 112 M126 112 Q138 119 150 112 M125 145 L125 198'}"/><text x="125" y="409" text-anchor="middle">${back?'COSTAS':'FRENTE'}</text></g>`}
export function mountProgress(){const section=document.createElement('section');section.id='body-progress';section.className='panel body-progress';section.innerHTML=`<div class="panel-head"><div><p class="eyebrow">O QUE MUDOU EM VOCÊ</p><h2>Sua evolução, região por região.</h2></div><span class="pill">MAPA DAS DOBRAS · MM</span></div><p class="body-intro">Explore as regiões e veja suas medidas mudarem entre as avaliações selecionadas.</p><div id="visual-empty" class="empty">Selecione duas avaliações diferentes, da mais antiga para a mais recente.</div><div class="body-layout"><div class="body-stage"><div class="body-dates"><span id="body-first">Antes</span><span id="body-last">Depois</span></div><svg id="body-svg" viewBox="0 0 510 430" role="img" aria-label="Representação esquemática dos sete locais de dobra, vista de frente e costas">${person(0,false)}${person(260,true)}<g id="body-markers"></g></svg><div class="body-legend"><span><i class="legend-initial"></i> Inicial (contorno)</span><span><i class="legend-current"></i> Posição atual</span><span><i class="legend-missing"></i> Sem dado</span></div><div class="playback"><button id="body-play" class="primary" type="button">▶ Ver transição</button><div><label for="body-slider">Antes → Depois</label><input id="body-slider" type="range" min="0" max="100" value="0" step="1" aria-describedby="body-position"><output id="body-position">Avaliação inicial</output></div></div><p class="muted">Entre os extremos, a transição é uma interpolação ilustrativa, não uma medição diária. A área de cada marcador é proporcional à espessura em mm, na mesma escala em todas as avaliações.</p></div><div class="region-side"><div id="region-detail" aria-live="polite"></div><p class="eyebrow">ESCOLHA UMA REGIÃO</p><div id="region-buttons"></div></div></div><p class="visual-limit">O boneco é esquemático: as dobras medem espessura em pontos específicos. Os marcadores não representam volume, quilos de gordura local, gordura visceral nem a aparência real do corpo. Áreas sem medição não recebem estimativas.</p><div id="progress-insights" class="progress-insights"></div>`;
$('#composition').before(section);
$('#region-buttons').innerHTML=Object.keys(folds).map((k,i)=>`<button type="button" data-region="${k}" aria-pressed="${k===selected}"><span class="region-number">${i+1}</span><span>${folds[k][0].replace('Dobra ','')}<small id="region-${k}">Sem comparação</small></span><span class="region-arrow">↗</span></button>`).join('');
$('#body-markers').onclick=e=>{const point=e.target.closest('[data-region]');if(point){selected=point.dataset.region;paint();}};
$('#region-buttons').onclick=e=>{const button=e.target.closest('[data-region]');if(button){selected=button.dataset.region;paint();}};
$('#body-slider').oninput=e=>{stop();position=Number(e.target.value)/100;paint()};
$('#body-play').onclick=()=>{if(frame){stop();return}if(matchMedia('(prefers-reduced-motion: reduce)').matches){position=position===1?0:1;paint();return}position=0;const begin=performance.now();$('#body-play').textContent='Ⅱ Pausar';function tick(now){position=Math.min(1,(now-begin)/2400);paint();if(position<1)frame=requestAnimationFrame(tick);else stop()}frame=requestAnimationFrame(tick)};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
mountResearch();}
function stop(){cancelAnimationFrame(frame);frame=0;$('#body-play').textContent='▶ Ver transição'}
export function updateProgress(a,b){first=a;last=b;stop();position=0;const ready=comparisonReady(a,b),hasPairs=ready&&foldTransition(a,b,0).some(r=>r.change);$('#visual-empty').hidden=ready;$('#body-slider').disabled=!hasPairs;$('#body-play').disabled=!hasPairs;$('#body-first').textContent=a?'Antes · '+d(a.date):'Antes';$('#body-last').textContent=b?'Depois · '+d(b.date):'Depois';paint();insights();}
function paint(){const ready=comparisonReady(first,last),rows=foldTransition(ready?first:null,ready?last:null,position);$('#body-slider').value=String(Math.round(position*100));$('#body-position').textContent=position===0?'Avaliação inicial':position===1?'Avaliação final':'Transição ilustrativa · '+Math.round(position*100)+'%';$('#body-slider').setAttribute('aria-valuetext',$('#body-position').textContent);
$('#body-markers').innerHTML=rows.map((r,i)=>{const [x,y]=locations[r.key],initial=markerRadius(r.start),current=markerRadius(r.value);return `<g data-region="${r.key}" class="body-point ${r.key===selected?'selected':''}"><title>${folds[r.key][0]}: ${r.value==null?'sem dado':f(r.value)+' mm'+(position>0&&position<1?' (interpolado)':'')}</title>${initial?`<circle class="initial-marker" cx="${x}" cy="${y}" r="${initial}"/>`:''}${current?`<circle class="current-marker" cx="${x}" cy="${y}" r="${current}"/>`:`<circle class="missing-marker" cx="${x}" cy="${y}" r="12"/>`}<text x="${x}" y="${y+4}" text-anchor="middle">${i+1}</text></g>`}).join('');
for(const r of rows){$(`#region-buttons [data-region="${r.key}"]`).setAttribute('aria-pressed',String(r.key===selected));$('#region-'+r.key).textContent=r.change?`${f(r.start)} → ${f(r.end)} mm · ${sign(r.change.absolute)} mm`:r.start!=null?'Final não informada':r.end!=null?'Inicial não informada':'Sem medidas';}
const row=rows.find(r=>r.key===selected);$('#region-detail').innerHTML=`<span class="pill">${locations[selected][2]==='front'?'VISTA FRONTAL':'VISTA POSTERIOR'}</span><h3>${folds[selected][0]}</h3>${row.change?`<div class="region-big">${sign(row.change.absolute)} <small>mm</small></div><p>${row.change.absolute<0?'A dobra registrada diminuiu':row.change.absolute>0?'A dobra registrada aumentou':'A dobra registrada não mudou'}${row.change.absolute!==0?' '+f(Math.abs(row.change.relative))+'%':''} no período.</p><p class="muted">${f(row.start)} mm no início · ${f(row.end)} mm no final. Isso descreve a espessura medida neste ponto, não a quantidade de gordura da região.</p>`:'<div class="region-big">— <small>mm</small></div><p>São necessárias medidas desta dobra nas duas avaliações para comparar.</p>'}`;
}
function insights(){const a=first,b=last,ready=comparisonReady(a,b),el=$('#progress-insights');if(!ready){el.innerHTML='<article><span class="pill">UM REGISTRO DE CADA VEZ</span><h3>Seu próximo ponto de comparação.</h3><p>Cadastre duas avaliações. Mesmo com campos em branco, as medidas em comum poderão ser comparadas.</p></article>';return}
const pairs=foldTransition(a,b,0).filter(r=>r.change),mass=fatMassChange(a,b),waist=delta(a.waist,b.waist),down=pairs.filter(r=>r.change.absolute<0).length,up=pairs.filter(r=>r.change.absolute>0).length;
let cards=[`<article><span class="pill">${days(a.date,b.date)} DIAS REGISTRADOS</span><h3>Seu ritmo tem uma história.</h3><p>${pairs.length?`${pairs.length} de 7 dobras comparáveis: ${down} diminuíram, ${up} aumentaram e ${pairs.length-down-up} não mudaram.`:'Ainda não há dobras em comum nas duas avaliações. Você pode completar seus registros depois.'}</p><small>Comparação dos valores registrados; mudanças pequenas podem incluir variação da medição.</small></article>`];
cards.push(mass?`<article><span class="pill">GORDURA TOTAL ESTIMADA</span><h3>${sign(mass.change)} kg no período</h3><p>${f(mass.start)} → ${f(mass.end)} kg de gordura estimada, combinando peso e BF de cada avaliação.</p><small>A diferença herda a incerteza do BF. Ela não informa de quais regiões a gordura veio.</small></article>`:`<article><span class="pill">CADA DADO TEM SEU PAPEL</span><h3>${waist?'Cintura: '+sign(waist.absolute)+' cm':'Complete a visão do conjunto.'}</h3><p>${waist?'A fita mostra a mudança da circunferência. Ela não separa músculo, gordura e outras variações.':'Para comparar a massa de gordura estimada, registre peso e as sete dobras, com idade e a mesma equação nas duas avaliações.'}</p></article>`);
cards.push(`<article><span class="pill">SUA REFERÊNCIA É VOCÊ</span><h3>Você está construindo um histórico.</h3><p>Compare o mesmo lado, a mesma posição e o mesmo método. Uma nova avaliação ajuda a entender se a mudança se mantém.</p><small>Estes comentários descrevem seus dados; não classificam seu corpo nem projetam resultados futuros.</small></article>`);el.innerHTML=cards.join('');}
function mountResearch(){const section=document.createElement('section');section.className='panel research';section.innerHTML=`<div class="panel-head"><div><p class="eyebrow">CURIOSIDADE COM REFERÊNCIA</p><h2>O que os estudos ajudam a entender.</h2></div><span class="pill">CIÊNCIA, SEM RANKING INVENTADO</span></div><div class="research-grid"><article><span class="research-number">585 <small>participantes</small></span><h3>O mesmo treino, respostas diferentes.</h3><p>Após 12 semanas de treino unilateral, a variação da área muscular do bíceps foi de −2% a +59%, medida por ressonância.</p><p class="muted">Hubal et al., 2005 · 342 mulheres e 243 homens. Área muscular não é circunferência do braço; essa faixa não é uma meta nem um percentil pessoal.</p><a href="https://pubmed.ncbi.nlm.nih.gov/15947721/" target="_blank" rel="noopener">Ler o estudo ↗</a></article><article><span class="research-number">−1,46 <small>p.p. de BF</small></span><h3>Uma média de estudos, não uma promessa.</h3><p>Uma meta-análise encontrou redução média de 1,46 ponto percentual no BF com treino de resistência, comparado a não fazer exercício.</p><p class="muted">Wewege et al., 2022 · adultos saudáveis; 58 estudos na revisão, 54 na meta-análise. Treinos de pelo menos 4 semanas; protocolos e durações variaram. Não é uma taxa mensal nem o percentual de pessoas que emagreceram.</p><a href="https://pubmed.ncbi.nlm.nih.gov/34536199/" target="_blank" rel="noopener">Ler a meta-análise ↗</a></article></div><div class="percentile-note"><strong>“Quantas pessoas conseguem a mesma evolução que eu?”</strong><p>Percentual não disponível. As fontes acima não fornecem uma distribuição comparável às suas medidas, ao seu período e ao seu perfil. O Forma não transforma médias de estudos em chances de sucesso ou rankings pessoais.</p></div>`;$('#comparison').after(section);}
